import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-06-08","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-06-08","date":"2020-06-08T00:00:00.000Z","updated":"2020-06-09T00:00:00.000Z","tags":["Ceph升级流程","Ceph计划功能","容器版本管理","Kubernetes集成","Ceph监控"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-08.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-08.md","lastUpdated":1780459816000}'),i={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-06-08.md"};function o(s,e,n,p,h,u){return a(),l("div",null,[...e[0]||(e[0]=[r('<p>在2020年6月8日的Ceph Orchestrator会议上，讨论了以下主要议题和决定事项：</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Ceph主要升级流程</strong></p><ul><li>确认了从Nautilus到Octopus的升级流程，与补丁发布相似，用户只需更新Rook部署的版本，Rook将处理升级过程中的所有必要步骤。</li></ul></li><li><p><strong>新增功能：计划功能</strong></p><ul><li>提出了名为“plan”的新功能，旨在提供调度器的预览，帮助用户了解哪些主机将接收服务。</li><li>讨论了是否需要新的命令关键字“plan”，或是否可以在现有的“apply”命令中添加参数来实现相同的功能。</li></ul></li><li><p><strong>监控堆栈容器版本管理</strong></p><ul><li>讨论了监控堆栈中使用的容器版本管理问题，建议使用配置文件来管理版本信息，并提供默认配置。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认Rook将负责处理Ceph主要升级的所有必要步骤，用户只需更新Rook部署的版本。</li><li>决定引入新的命令关键字“plan”，以便用户可以预览已应用的服务规范的结果。</li><li>同意将容器版本信息从代码中移出，使用配置文件来管理，并允许用户自定义容器版本。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>优化Rook的升级流程，确保升级过程的稳定性和可靠性。</li><li>开发并测试“plan”功能的实现，确保其能够准确预览服务规范的结果。</li><li>将容器版本信息从代码中移出，并创建相应的配置文件，确保用户可以自定义容器版本。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了如何使驱动组（Drive Groups）在Kubernetes环境中工作，提出了使用节点亲和性等方法来实现。</li></ul><p>会议还讨论了将未决问题和讨论移至邮件列表或聊天群组，以便进一步讨论和决策。</p>',10)])])}const d=t(i,[["render",o]]);export{c as __pageData,d as default};
